/**
 * Logotipos de Amaranto Morelia incrustados como data URI.
 *
 * Se guardan en base64 y no como archivos .png sueltos a propósito:
 * `tint()` los dibuja en un <canvas> y llama a `toDataURL()` para recolorearlos.
 * Un PNG cargado desde disco (file://) o desde otro origen contamina el canvas
 * y esa llamada fallaría; un data URI se considera del mismo origen y siempre funciona.
 *
 * Expone: window.Amaranto.LOGOS = { word, mark }
 */
(function (global) {
  "use strict";

  var Amaranto = (global.Amaranto = global.Amaranto || {});

  Amaranto.LOGOS = {word:'data:image/png;base64,',mark:'data:image/png;base64,'}


  Object.freeze(Amaranto.LOGOS);
})(window);
